#!name=横店电影小程序
#!desc=fmz200/wool_scripts · 某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思

[MITM]
hostname = api.hengdianfilm.com

[Rewrite]
request if ${url} ~= /^https?:\/\/api\.hengdianfilm\.com\/\/cinema\/queryAvailableBannerInfo\/1/i then redirect(302, "https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/hengdian.json")
request if ${url} ~= /^https?:\/\/api\.hengdianfilm\.com\/\/cinema\/queryAvailableBannerInfo\/2\?cid=/i then reject_dict(200)
request if ${url} ~= /^https?:\/\/api\.hengdianfilm\.com\/\/cinema\/queryAvailableBannerInfo\/4\?cid=/i then reject_dict(200)
